package com.example.workout.shoe.service; import com.example.workout.common.exception.*; import com.example.workout.shoe.entity.RunningShoeEntity; import com.example.workout.shoe.mapper.RunningShoeEntityMapper; import com.example.workout.shoe.model.RunningShoe; import com.example.workout.shoe.repository.RunningShoeRepository; import com.example.workout.workout.repository.WorkoutRepository; import java.time.OffsetDateTime; import java.util.Set; import lombok.RequiredArgsConstructor; import lombok.extern.slf4j.Slf4j; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor @Slf4j @Transactional public class RunningShoeServiceImpl implements RunningShoeService { private final RunningShoeRepository repository; private final WorkoutRepository workoutRepository; public RunningShoe create(RunningShoe shoe){OffsetDateTime now=OffsetDateTime.now();shoe.setCreatedAt(now);shoe.setUpdatedAt(now);RunningShoeEntity saved=repository.save(RunningShoeEntityMapper.toEntity(shoe));log.info("[SHOE] - ACTION: createShoe: shoeId: {}",saved.getId());return RunningShoeEntityMapper.toModel(saved);} @Transactional(readOnly=true) public RunningShoe get(Long id){return RunningShoeEntityMapper.toModel(find(id));} @Transactional(readOnly=true) public Page<RunningShoe> search(Pageable p){return repository.findAll(p).map(RunningShoeEntityMapper::toModel);} public RunningShoe patch(Long id,RunningShoe p,Set<String> f){RunningShoeEntity e=find(id);if(f.contains("brand"))e.setBrand(p.getBrand());if(f.contains("model"))e.setModel(p.getModel());if(f.contains("nickname"))e.setNickname(p.getNickname());if(f.contains("purchaseDate"))e.setPurchaseDate(p.getPurchaseDate());if(f.contains("initialDistanceMeters"))e.setInitialDistanceMeters(p.getInitialDistanceMeters());if(f.contains("active"))e.setActive(p.getActive());if(f.contains("notes"))e.setNotes(p.getNotes());e.setUpdatedAt(OffsetDateTime.now());return RunningShoeEntityMapper.toModel(repository.save(e));} public void delete(Long id){RunningShoeEntity e=find(id);if(workoutRepository.existsByShoeId(id))throw new AppException(AppError.SHOE_IN_USE);repository.delete(e);log.info("[SHOE] - ACTION: deleteShoe: shoeId: {}",id);} private RunningShoeEntity find(Long id){return repository.findById(id).orElseThrow(()->new AppException(AppError.SHOE_NOT_FOUND));}}
